const measurements=[['height','Height','core','linear'],['shoulder','Shoulder width','core','linear'],['chest','Chest / bust circumference','core','circumference'],['waist','Waist circumference','core','circumference'],['hip','Hip circumference','core','circumference'],['neck','Neck circumference','upper','circumference'],['armhole','Armhole circumference','upper','circumference'],['bicep','Bicep circumference','upper','circumference'],['elbow','Elbow circumference','upper','circumference'],['wrist','Wrist circumference','upper','circumference'],['shoulderToWaist','Shoulder to waist','upper','linear'],['shoulderToHip','Shoulder to hip','upper','linear'],['shoulderToElbow','Shoulder to elbow','upper','linear'],['shoulderToWrist','Shoulder to wrist','upper','linear'],['elbowToWrist','Elbow to wrist','upper','linear'],['sleeve','Sleeve length','upper','linear'],['waistToHip','Waist to hip','lower','linear'],['waistToKnee','Waist to knee','lower','linear'],['waistToAnkle','Waist to floor','lower','linear'],['trouserLength','Trouser length','lower','linear'],['inseam','Inseam','lower','linear'],['outseam','Outseam','lower','linear'],['thigh','Thigh circumference','lower','circumference'],['knee','Knee circumference','lower','circumference'],['calf','Calf circumference','lower','circumference'],['ankle','Ankle circumference','lower','circumference']];
const $=s=>document.querySelector(s),state={height:null,values:Object.fromEntries(measurements.map(([k])=>[k,null])),captures:{},analyses:{},result:null,stream:null,activeGroup:'core'};const format=v=>`${Number(v).toFixed(1)} in`;
function toast(m){const e=$('#toast');e.textContent=m;e.classList.add('show');setTimeout(()=>e.classList.remove('show'),2800)}function stopCamera(){if(state.stream)state.stream.getTracks().forEach(t=>t.stop());state.stream=null}function requireHeight(){const i=$('#calibrationHeight'),v=Number(i.value);if(!i.validity.valid||!Number.isFinite(v)||v<=0){toast('Enter a valid height before taking photos.');i.focus();return false}state.height=v;state.values.height=v;return true}function showScreen(id){document.querySelectorAll('.screen').forEach(s=>s.classList.toggle('active',s.id===id));$('#restartButton').hidden=id==='home';stopCamera();if(id==='review')renderMeasurements();if(id==='summary')renderSummary();window.scrollTo({top:0,behavior:'smooth'})}
async function openCamera(view){try{stopCamera();state.stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'},width:{ideal:1080},height:{ideal:1920}},audio:false});const v=$(`#${view}Video`);v.srcObject=state.stream;$(`#${view}Preview`).hidden=true;$(`#${view}Outline`).hidden=true;$(`#${view}Message`).hidden=true;$(`#${view}Capture`).textContent='Capture photo'}catch(e){toast('Camera access is required for the two-photo measurement flow.');$(`#${view}Message`).textContent='Camera unavailable. Allow camera access and try again.'}}function snap(view){const v=$(`#${view}Video`),c=document.createElement('canvas');c.width=v.videoWidth||1080;c.height=v.videoHeight||1920;c.getContext('2d').drawImage(v,0,0,c.width,c.height);state.captures[view]=c.toDataURL('image/jpeg',.9);const p=$(`#${view}Preview`);p.src=state.captures[view];p.hidden=false;stopCamera();$(`#${view}Capture`).textContent=view==='front'?'Process front outline':'Process both outlines';$(`#${view}Retake`).hidden=false}
async function analyze(view){const provider=state.visionProvider||await window.tailorScanVision.createProvider();state.visionProvider=provider;state.analyses[view]=await provider.analyzeFrame({id:view,angle:view==='front'?0:90,image:state.captures[view]});return state.analyses[view]}function drawOutline(view,analysis,result){const c=$(`#${view}Outline`),x=c.getContext('2d'),m=analysis.segmentationMaskRef;c.width=m.width;c.height=m.height;x.fillStyle='#f8f5ee';x.fillRect(0,0,c.width,c.height);x.fillStyle='#163b35';result.outlines[view].forEach(p=>x.fillRect(p.x*c.width,p.y*c.height,2,2));x.fillStyle='#cf9a4a';Object.values(result.landmarks[view]).filter(p=>p&&Number.isFinite(p.x)).forEach(p=>{x.beginPath();x.arc(p.x*c.width,p.y*c.height,3,0,Math.PI*2);x.fill()});c.hidden=false;$(`#${view}Preview`).hidden=true}
async function processPhotos(){try{toast('Creating 2D outlines and locating landmarks…');if(!state.analyses.front)await analyze('front');await analyze('side');state.result=window.tailorScanSilhouette.measure({front:state.analyses.front,side:state.analyses.side,heightInches:state.height});Object.entries(state.result.measurements).forEach(([n,v])=>{if(Number.isFinite(v))state.values[n]=v});drawOutline('front',state.analyses.front,state.result);drawOutline('side',state.analyses.side,state.result);setTimeout(()=>showScreen('review'),550)}catch(e){toast(`Photo could not be measured: ${e.message}`)}}async function handleCapture(view){if(state.stream)return snap(view);if(!state.captures[view])return openCamera(view);if(view==='front'){try{toast('Creating front outline…');await analyze('front');showScreen('side')}catch(e){toast(`Retake the front photo: ${e.message}`)}}else await processPhotos()}function retake(view){state.captures[view]=null;state.analyses[view]=null;$(`#${view}Retake`).hidden=true;openCamera(view)}
function renderMeasurements(){$('#referenceStatus').textContent=`Scale: ${format(state.height)} over each detected head-to-floor outline. “Measured” fields are 2D landmark lengths; “Manual tape” fields are never inferred.`;const l=$('#measurementForm');l.innerHTML=measurements.filter(([, ,g])=>g===state.activeGroup).map(([k,label,,type])=>`<div class="measure-row ${type}"><label for="${k}">${label}<small>${type==='circumference'?'Manual tape':'Measured from 2D landmarks'}</small></label><div class="measure-input"><input id="${k}" type="number" min="0" max="120" step="0.1" value="${Number.isFinite(state.values[k])?Number(state.values[k]).toFixed(1):''}" placeholder="${type==='circumference'?'Enter':'—'}" inputmode="decimal"><span>in</span></div></div>`).join('');l.querySelectorAll('input').forEach(i=>i.addEventListener('input',()=>state.values[i.id]=i.value===''?null:Number(i.value)))}function renderSummary(){$('#summaryList').innerHTML=measurements.map(([k,label,,type])=>`<div class="summary-row"><span>${label}<small>${type==='circumference'?'manual':'2D landmark'}</small></span><strong>${Number.isFinite(state.values[k])?format(state.values[k]):'Not entered'}</strong></div>`).join('')}function output(){return{schema_version:'2.0',method:'height-scaled front/side 2D silhouettes',unit:'in',measurements:{...state.values},measurement_sources:Object.fromEntries(measurements.map(([k,,,type])=>[k,type==='circumference'?'manual tape entry':(k==='height'?'imputed height':state.result?.diagnostics[k]||'unavailable')])),outlines:state.result?{front:state.result.outlines.front,side:state.result.outlines.side}:null}}
document.querySelectorAll('[data-go]').forEach(b=>b.addEventListener('click',()=>{const id=b.dataset.go;if(id==='front'&&!requireHeight())return;showScreen(id)}));$('#restartButton').addEventListener('click',()=>showScreen('home'));$('#frontCapture').addEventListener('click',()=>handleCapture('front'));$('#sideCapture').addEventListener('click',()=>handleCapture('side'));$('#frontRetake').addEventListener('click',()=>retake('front'));$('#sideRetake').addEventListener('click',()=>retake('side'));document.querySelectorAll('.tab').forEach(t=>t.addEventListener('click',()=>{state.activeGroup=t.dataset.group;document.querySelectorAll('.tab').forEach(i=>i.classList.toggle('active',i===t));renderMeasurements()}));$('#summaryButton').addEventListener('click',()=>showScreen('summary'));$('#saveButton').addEventListener('click',()=>{const p=JSON.parse(localStorage.getItem('tailorScanProfiles')||'[]'),name=$('#profileName').value.trim()||'Unnamed client';p.unshift({id:Date.now(),name,...output(),savedAt:new Date().toISOString()});localStorage.setItem('tailorScanProfiles',JSON.stringify(p));toast(`${name}'s profile saved on this device.`)});window.tailorScan=Object.freeze({buildMeasurementOutput:output});
